+// Regla de auditoría de empresa (EMBA): el motivo de anulación tiene al menos 10 caracteres sin contar los
+// espacios de los bordes.
+export const MOTIVO_MIN_CARACTERES = 10;
+
+// RF-005, ADR-002: anula una factura emitida. Devuelve una factura nueva "anulada"; la original no cambia.
+export function anularFactura(factura, motivo) {
+  if (!factura || factura.estado !== "emitida") throw new Error("Solo se puede anular una factura emitida");
+  const motivoLimpio = typeof motivo === "string" ? motivo.trim() : "";
+  if (motivoLimpio.length < MOTIVO_MIN_CARACTERES)
+    throw new Error(`El motivo de anulación necesita al menos ${MOTIVO_MIN_CARACTERES} caracteres`);
+  return Object.freeze({ ...factura, estado: "anulada", motivo: motivoLimpio });
+}
